-- ───────────────────────────────────────────────────────────────────
-- 20260707_suppliers.sql — Import & enrichissement de l'annuaire fournisseurs.
-- Source : « Liste_des_fournisseurs.xlsx » (Service Comptabilité Astorya).
-- La table `suppliers` existe déjà (sql/20260615_stock_catalogue.sql) ; on
-- enrichit ici les colonnes payment_terms + data jsonb avec, pour chaque
-- fournisseur :
--   data.cost_bracket     répartition par coûts annuels (+50 000€ … -5 000€)
--   data.importance       niveau (strategique / important / standard / secondaire)
--   data.importance_note  note 2..5 (dérivée du volume d'achat, éditable)
--   data.account_number   n° de compte comptable (401…)
--   data.payment_type     type de paiement (prélèvement / virement / carte…)
--   data.invoice_mailbox  où récupérer / faire router la facture
--   data.tva_intracom     TVA intracom mentionnée sur les factures
-- Idempotent : ON CONFLICT (name) DO UPDATE fusionne le jsonb (data || EXCLUDED.data),
-- ne recrée pas les fournisseurs existants et préserve leur catégorie/contacts.
-- RLS déjà posée sur `suppliers` par la migration stock_catalogue.
-- ───────────────────────────────────────────────────────────────────

ON CONFLICT (name) DO UPDATE SET
  payment_terms = COALESCE(NULLIF(EXCLUDED.payment_terms,''), suppliers.payment_terms),
  data = suppliers.data || EXCLUDED.data,
  updated_at = now();
